command:
/**
 * Starship Emergency Repairs
 * Attempt mid-combat DC 12 INT/CON check to patch hull breaches or restore damaged components.
 */
const token = canvas.tokens.controlled[0];
const actor = token?.actor;
const isShip = actor?.type === "darkspace.Ship";

let engineerMod = 0;
let label = "Engineer";

if (actor && !isShip) {
  engineerMod = Math.max(actor.system?.abilities?.int?.mod ?? 0, actor.system?.abilities?.con?.mod ?? 0);
  label = actor.name;
} else if (actor && isShip) {
  engineerMod = actor.system?.abilities?.con?.mod ?? 0;
  label = `${actor.name} Automated Damage Control`;
}

new Dialog({
  title: "Emergency Starship Repairs",
  content: `
    <form class="darkspace-dialog">
      <p><b>Operator:</b> ${label} (Mod: ${engineerMod >= 0 ? '+' : ''}${engineerMod})</p>
      <p>Attempt mid-combat damage control (<b>DC 12</b>). A success restores <b>1d8 Hull Points</b> or clears a damaged component condition.</p>
    </form>
  `,
  buttons: {
    repair: {
      icon: '<i class="fas fa-wrench"></i>',
      label: "Attempt Repair",
      callback: async () => {
        const roll = await new Roll(`1d20 + ${engineerMod}`).evaluate();
        const rollHtml = await roll.render();
        const success = roll.total >= 12;

        let resultHtml = "";
        if (success) {
          const hpRoll = await new Roll("1d8").evaluate();
          resultHtml = `
            <div style="background: rgba(0, 150, 0, 0.15); border: 1px solid #4CAF50; padding: 8px; border-radius: 4px; margin-top: 8px;">
              <b style="color: #4CAF50;"><i class="fas fa-tools"></i> Repairs Successful!</b>
              <p style="margin: 4px 0 0 0;">Hull breach sealed / power conduits restored! Repaired <b>${hpRoll.total} HP</b> (or un-damaged one component).</p>
            </div>
          `;
          if (isShip) {
            const currentHp = actor.system.attributes.hp.value;
            const maxHp = actor.system.attributes.hp.max;
            await actor.update({ "system.attributes.hp.value": Math.min(maxHp, currentHp + hpRoll.total) });
          }
        } else {
          resultHtml = `
            <div style="background: rgba(200, 0, 0, 0.15); border: 1px solid #F44336; padding: 8px; border-radius: 4px; margin-top: 8px;">
              <b style="color: #F44336;"><i class="fas fa-fire"></i> Repairs Failed!</b>
              <p style="margin: 4px 0 0 0;">Conduits blow back or plasma torch jams! Action spent without restoring hull integrity.</p>
            </div>
          `;
        }

        await ChatMessage.create({
          user: game.user._id,
          speaker: ChatMessage.getSpeaker({ actor }),
          flavor: "<b>Damage Control Check (DC 12)</b>",
          content: `${rollHtml}${resultHtml}`
        });
      }
    },
    cancel: {
      icon: '<i class="fas fa-times"></i>',
      label: "Cancel"
    }
  },
  default: "repair"
}).render(true);
